23	// LocalReviewManifest records one local `entire review` invocation. It lets
24	// `entire review --fix <session-id>` use a single session id as the lookup
25	// handle while still loading sibling agent outputs from the same review run.
26	type LocalReviewManifest struct {
27		Version         int              `json:"version"`
28		WorktreePath    string           `json:"worktree_path"`
29		CreatedAt       time.Time        `json:"created_at"`
30		StartingSHA     string           `json:"starting_sha,omitempty"`
31		Sources         []ManifestSource `json:"sources"`
32		AggregateOutput string           `json:"aggregate_output,omitempty"`
33	}
34	
35	type ManifestSource struct {
36		SessionID string `json:"session_id"`
37		Agent     string `json:"agent"`
38		Label     string `json:"label"`
39		Status    string `json:"status,omitempty"`
40		Output    string `json:"output,omitempty"`
41	}
