43	func buildLocalReviewManifestFromSummary(
44		worktreeRoot string,
45		headSHA string,
46		summary reviewtypes.RunSummary,
47		states []*session.State,
48		aggregateOutput string,
49	) LocalReviewManifest {
50		manifest := LocalReviewManifest{
51			Version:         localReviewManifestVersion,
52			WorktreePath:    worktreeRoot,
53			CreatedAt:       summary.StartedAt,
54			StartingSHA:     headSHA,
55			AggregateOutput: strings.TrimSpace(aggregateOutput),
56		}
57		usedSessions := map[string]bool{}
58		for _, run := range summary.AgentRuns {
59			st := matchReviewSessionState(worktreeRoot, headSHA, summary.StartedAt, run.Name, states, usedSessions)
60			if st == nil || st.SessionID == "" {
61				continue
62			}
63			usedSessions[st.SessionID] = true
64			manifest.Sources = append(manifest.Sources, ManifestSource{
65				SessionID: st.SessionID,
66				Agent:     run.Name,
67				Label:     labelForReviewAgent(run.Name),
68				Status:    run.Status.String(),
69				Output:    agentRunOutput(run),
70			})
71		}
72		return manifest
73	}
