75	func localReviewManifestFromCurrentState(
76		ctx context.Context,
77		worktreeRoot string,
78		headSHA string,
79		summary reviewtypes.RunSummary,
80		aggregateOutput string,
81	) (LocalReviewManifest, []*session.State, error) {
82		store, err := session.NewStateStore(ctx)
83		if err != nil {
84			return LocalReviewManifest{}, nil, fmt.Errorf("create session state store: %w", err)
85		}
86		states, err := store.List(ctx)
87		if err != nil {
88			return LocalReviewManifest{}, nil, fmt.Errorf("list session states: %w", err)
89		}
90		return buildLocalReviewManifestFromSummary(worktreeRoot, headSHA, summary, states, aggregateOutput), states, nil
91	}
