93	// explainEmptyManifest returns a single-line diagnostic explaining why
94	// matchReviewSessionState produced no matches for any agent run in summary.
95	// It inspects the candidate session states against the same filters used by
96	// the matcher and reports the most likely cause: missing tag, worktree path
97	// mismatch, BaseCommit mismatch, StartedAt window, or AgentType mismatch.
98	//
99	// The diagnostic surfaces in the user-facing warning printed by
100	// warnManifestNotWritten when the manifest has no sources, so the user can
101	// distinguish a true env-handshake failure from one of the four other
102	// post-tag filter rejections.
103	//
104	// Filter precedence in this function matches matchReviewSessionState so the
105	// reported cause aligns with what the matcher actually decided.
106	func explainEmptyManifest(
107		worktreeRoot string,
108		headSHA string,
109		summary reviewtypes.RunSummary,
110		states []*session.State,
111	) string {
112		if len(states) == 0 {
113			return "no session states found (lifecycle hook never created session state for any agent in this run)"
114		}
115		tagged := make([]*session.State, 0, len(states))
116		for _, st := range states {
117			if st != nil && st.Kind == session.KindAgentReview {
118				tagged = append(tagged, st)
119			}
120		}
121		if len(tagged) == 0 {
122			return fmt.Sprintf("found %d session state(s) but none tagged as a review session (env-var handshake did not reach the hook)", len(states))
123		}
124		// At least one tagged session exists. Check each post-tag filter against
125		// any one of the run's agents — we just need one representative cause.
126		// Pick the first agent in summary.AgentRuns since they all share the
127		// same worktree/SHA/StartedAt window.
128		var runName string
129		if len(summary.AgentRuns) > 0 {
130			runName = summary.AgentRuns[0].Name
131		}
132		wantType := agentTypeForReviewAgent(runName)
133		for _, st := range tagged {
134			if worktreeRoot != "" && st.WorktreePath != "" && st.WorktreePath != worktreeRoot {
135				return fmt.Sprintf("found %d tagged review session(s) but worktree path mismatch: state=%q, run=%q", len(tagged), st.WorktreePath, worktreeRoot)
136			}
137		}
138		for _, st := range tagged {
139			if headSHA != "" && st.BaseCommit != "" && st.BaseCommit != headSHA {
140				return fmt.Sprintf("found %d tagged review session(s) but BaseCommit mismatch: state=%q, run=%q (HEAD moved between review start and first agent turn?)", len(tagged), st.BaseCommit, headSHA)
141			}
142		}
143		for _, st := range tagged {
144			if !summary.StartedAt.IsZero() && st.StartedAt.Before(summary.StartedAt.Add(-5*time.Second)) {
145				return fmt.Sprintf("found %d tagged review session(s) but they started before the review run window (stale session state from a prior run?)", len(tagged))
146			}
147		}
148		for _, st := range tagged {
149			if wantType != "" && st.AgentType != "" && st.AgentType != wantType {
150				return fmt.Sprintf("found %d tagged review session(s) but AgentType mismatch: state=%q, run=%q", len(tagged), st.AgentType, wantType)
151			}
152		}
153		return fmt.Sprintf("found %d tagged review session(s) but matcher rejected all of them (no filter explained the rejection — please report this as a bug)", len(tagged))
154	}
