156	func matchReviewSessionState(
157		worktreeRoot string,
158		headSHA string,
159		runStartedAt time.Time,
160		agentName string,
161		states []*session.State,
162		used map[string]bool,
163	) *session.State {
164		wantAgentType := agentTypeForReviewAgent(agentName)
165		var best *session.State
166		for _, st := range states {
167			if st == nil || used[st.SessionID] || st.Kind != session.KindAgentReview {
168				continue
169			}
170			if worktreeRoot != "" && st.WorktreePath != "" && st.WorktreePath != worktreeRoot {
171				continue
172			}
173			if headSHA != "" && st.BaseCommit != "" && st.BaseCommit != headSHA {
174				continue
175			}
176			if !runStartedAt.IsZero() && st.StartedAt.Before(runStartedAt.Add(-5*time.Second)) {
177				continue
178			}
179			if wantAgentType != "" && st.AgentType != "" && st.AgentType != wantAgentType {
180				continue
181			}
182			if best == nil || st.StartedAt.After(best.StartedAt) {
183				best = st
184			}
185		}
186		return best
187	}
