204	func agentRunOutput(run reviewtypes.AgentRun) string {
205		if narrative := joinAssistantText(run.Buffer); narrative != "" {
206			return narrative
207		}
208		if run.Err != nil {
209			return "Failed: " + run.Err.Error()
210		}
211		return ""
212	}
