244	func resolveLocalReviewManifestBySessionID(ctx context.Context, worktreeRoot, sessionID string) (LocalReviewManifest, ManifestSource, error) {
245		manifests, err := loadLocalReviewManifests(ctx, worktreeRoot)
246		if err != nil {
247			return LocalReviewManifest{}, ManifestSource{}, err
248		}
249	
250		var (
251			matches       []LocalReviewManifest
252			sourceMatches []ManifestSource
253		)
254		for _, manifest := range manifests {
255			for _, source := range manifest.Sources {
256				if source.SessionID == sessionID || strings.HasPrefix(source.SessionID, sessionID) {
257					matches = append(matches, manifest)
258					sourceMatches = append(sourceMatches, source)
259					break
260				}
261			}
262		}
263		switch len(matches) {
264		case 0:
265			return LocalReviewManifest{}, ManifestSource{}, fmt.Errorf("review session %q not found", sessionID)
266		case 1:
267			return matches[0], sourceMatches[0], nil
268		default:
269			return LocalReviewManifest{}, ManifestSource{}, fmt.Errorf("review session prefix %q is ambiguous", sessionID)
270		}
271	}
272	
273	func loadLocalReviewManifests(ctx context.Context, worktreeRoot string) ([]LocalReviewManifest, error) {
274		dir, err := localReviewManifestDir(ctx)
275		if err != nil {
276			return nil, err
277		}
278		entries, err := os.ReadDir(dir)
279		if errors.Is(err, os.ErrNotExist) {
280			return nil, nil
281		}
282		if err != nil {
283			return nil, fmt.Errorf("read review manifest dir: %w", err)
284		}
285	
286		manifests := make([]LocalReviewManifest, 0, len(entries))
287		for _, entry := range entries {
288			if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
289				continue
290			}
291			b, readErr := os.ReadFile(filepath.Join(dir, entry.Name())) //nolint:gosec // entry names come directly from os.ReadDir(dir).
292			if readErr != nil {
293				return nil, fmt.Errorf("read review manifest %s: %w", entry.Name(), readErr)
294			}
295			var manifest LocalReviewManifest
296			if err := json.Unmarshal(b, &manifest); err != nil {
297				return nil, fmt.Errorf("decode review manifest %s: %w", entry.Name(), err)
298			}
299			if worktreeRoot != "" && manifest.WorktreePath != "" && manifest.WorktreePath != worktreeRoot {
300				continue
301			}
302			manifests = append(manifests, manifest)
303		}
304		sort.SliceStable(manifests, func(i, j int) bool {
305			return manifests[i].CreatedAt.After(manifests[j].CreatedAt)
306		})
307		return manifests, nil
308	}
309	
310	func localReviewManifestDir(ctx context.Context) (string, error) {
311		worktreeRoot, err := paths.WorktreeRoot(ctx)
312		if err != nil {
313			return "", fmt.Errorf("resolve worktree root: %w", err)
314		}
315		commonDir, err := runGit(ctx, worktreeRoot, "rev-parse", "--git-common-dir")
316		if err != nil {
317			return "", fmt.Errorf("resolve git common dir: %w", err)
318		}
319		commonDir = strings.TrimSpace(commonDir)
320		if commonDir == "" {
321			return "", errors.New("git common dir is empty")
322		}
323		if !filepath.IsAbs(commonDir) {
324			commonDir = filepath.Join(worktreeRoot, commonDir)
325		}
326		return filepath.Join(commonDir, "entire-review", "manifests"), nil
327	}
328	
329	func localReviewManifestFilename(manifest LocalReviewManifest) string {
330		name := manifest.CreatedAt.UTC().Format("20060102T150405")
331		if len(manifest.Sources) > 0 && manifest.Sources[0].SessionID != "" {
332			name += "-" + safeManifestFilenamePart(manifest.Sources[0].SessionID)
333		}
334		return name + ".json"
335	}
336	
337	func safeManifestFilenamePart(value string) string {
338		value = strings.TrimSpace(value)
339		if value == "" {
340			return "review"
341		}
342		var b strings.Builder
343		for _, r := range value {
344			if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_' || r == '.' {
345				b.WriteRune(r)
346				continue
347			}
348			b.WriteByte('-')
349		}
350		return b.String()
351	}
