18	func TestLocalReviewManifest_ResolveByAnySessionID(t *testing.T) {
19		repoRoot := t.TempDir()
20		testutil.InitRepo(t, repoRoot)
21		t.Chdir(repoRoot)
22	
23		manifest := LocalReviewManifest{
24			Version:      1,
25			WorktreePath: repoRoot,
26			CreatedAt:    time.Date(2026, 5, 7, 10, 0, 0, 0, time.UTC),
27			StartingSHA:  "abc123",
28			Sources: []ManifestSource{
29				{
30					SessionID: "claude-session",
31					Agent:     "claude-code",
32					Label:     "Claude Code",
33					Output:    "H1. Claude finding",
34				},
35				{
36					SessionID: "codex-session",
37					Agent:     manifestTestCodexAgent,
38					Label:     "Codex",
39					Output:    "M1. Codex finding",
40				},
41			},
42			AggregateOutput: "Combined summary",
43		}
44	
45		if err := writeLocalReviewManifest(context.Background(), manifest); err != nil {
46			t.Fatalf("writeLocalReviewManifest: %v", err)
47		}
48	
49		got, matched, err := resolveLocalReviewManifestBySessionID(context.Background(), repoRoot, "codex-session")
50		if err != nil {
51			t.Fatalf("resolveLocalReviewManifestBySessionID: %v", err)
52		}
53		if matched.SessionID != "codex-session" {
54			t.Fatalf("matched session = %q, want codex-session", matched.SessionID)
55		}
56		if len(got.Sources) != 2 {
57			t.Fatalf("sources = %d, want 2", len(got.Sources))
58		}
59		if got.AggregateOutput != "Combined summary" {
60			t.Fatalf("aggregate output = %q", got.AggregateOutput)
61		}
62	}
