// TestExplainEmptyManifest_UnknownAgentInSummary covers the case where the
// run's agent name does not resolve in the agent registry. Without an
// explicit branch this falls through to the catch-all "please report this
// as a bug" message, misleading users when the real cause is a stale or
// misspelled agent identifier.
func TestExplainEmptyManifest_UnknownAgentInSummary(t *testing.T) {
	t.Parallel()
	started := time.Now()
	summary := reviewtypes.RunSummary{
		StartedAt: started,
		AgentRuns: []reviewtypes.AgentRun{{Name: "not-a-real-agent"}},
	}
	states := []*session.State{
		{
			SessionID:    "s1",
			Kind:         session.KindAgentReview,
			WorktreePath: "/repo",
			BaseCommit:   "abc123",
			StartedAt:    started.Add(time.Second),
			AgentType:    agenttypes.AgentType("Claude Code"),
		},
	}
	got := explainEmptyManifest("/repo", "abc123", summary, states)
	if !strings.Contains(got, "not-a-real-agent") {
		t.Errorf("reason = %q, want unknown agent name in message", got)
	}
	if !strings.Contains(got, "agent registry") {
		t.Errorf("reason = %q, want hint pointing at the agent registry", got)
	}
	if strings.Contains(got, "please report this as a bug") {
		t.Errorf("reason = %q, must not fall through to bug-report catch-all", got)
	}
}

