for _, st := range tagged {
	if wantType != "" && st.AgentType != "" && st.AgentType != wantType {
		return fmt.Sprintf("found %d tagged review session(s) but AgentType mismatch: state=%q, run=%q", len(tagged), st.AgentType, wantType)
	}
}
// If we got here with runName set but wantType empty, the registry lookup
// failed. The AgentType filter was skipped entirely, so the matcher's
// rejection isn't a real "AgentType mismatch" — it's an upstream identity
// problem that the catch-all would misattribute as "please report this".
if runName != "" && wantType == "" {
	return fmt.Sprintf("found %d tagged review session(s) but agent %q is not registered in the agent registry (AgentType filter was skipped; check for a stale or misspelled agent name)", len(tagged), runName)
}
return fmt.Sprintf("found %d tagged review session(s) but matcher rejected all of them (no filter explained the rejection — please report this as a bug)", len(tagged))

